from __future__ import annotations

import argparse
import html
import json
import re
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


DOC_NAMES = (
    "README.md",
    "RESEARCH_SPEC.md",
    "HANDOFF.md",
    "STATUS.md",
)
RUNNER_RE = re.compile(
    r"(?:^|[_-])(run|runner|backtest|monitor|pipeline|screener|refresh|build)(?:[_-]|\.|$)",
    re.IGNORECASE,
)
ARTIFACT_RE = re.compile(
    r"(backtest|result|summary|metrics|trades|equity|drawdown|wfa|walk.forward|"
    r"event.study|monitor|verdict|gate|status|readiness)",
    re.IGNORECASE,
)
TEXT_SUFFIXES = {".md", ".txt", ".json", ".yaml", ".yml", ".toml"}
SKIP_DIRS = {
    ".git",
    ".pytest_cache",
    "__pycache__",
    ".venv",
    "node_modules",
    "archive",
}

EVIDENCE_CHECKS = {
    "hypothesis": (
        "hypothesis",
        "thesis",
        "economic logic",
        "研究假設",
        "假設",
    ),
    "costs_slippage": (
