        "look-ahead",
        "lookahead",
        "point-in-time",
        "usable_from",
        "observed_at",
        "前視",
        "時間可用",
    ),
    "survivorship_universe": (
        "survivorship",
        "historical constituents",
        "point-in-time universe",
        "delisted",
        "存活者",
        "歷史成分",
    ),
    "out_of_sample": (
        "out-of-sample",
        "out of sample",
        "walk-forward",
        "walk forward",
        "rolling validation",
        "oos",
        "樣本外",
        "滾動驗證",
    ),
    "parameter_robustness": (
        "parameter sensitivity",
        "robustness",
        "stress test",
        "plateau",
        "sensitivity",
        "參數敏感",
        "穩健",
        "壓力測試",
    ),
